function load(){try{const raw=JSON.parse(TintaStore.unpackText(localStorage.getItem(STORE))||'null');if(!raw||typeof raw!=='object')return;const ui={},buttonStyles={},cardStyles={};let skipped=0;if(raw.ui&&typeof raw.ui==='object')Object.entries(raw.ui).forEach(([id,value])=>{try{Object.assign(ui,TintaStates.normalize({[id]:value},BY_ID));}catch(e){skipped++;}});if(raw.buttonStyles&&typeof raw.buttonStyles==='object')Object.entries(raw.buttonStyles).forEach(([id,value])=>{try{Object.assign(buttonStyles,TintaButtonStyle.normalize({[id]:value},BY_ID));}catch(e){skipped++;}});if(raw.cardStyles&&typeof raw.cardStyles==='object')Object.entries(raw.cardStyles).forEach(([id,value])=>{try{Object.assign(cardStyles,TintaCardStyle.normalize({[id]:value},BY_ID));}catch(e){skipped++;}});const draft=normalizedDraft({...raw,ui,buttonStyles,cardStyles,selected:Array.isArray(raw.selected)?raw.selected.filter(id=>Object.hasOwn(BY_ID,id)):[]});Object.assign(state,draft);if(skipped)toast('Se conservó tu selección. Algunos estados o estilos ya no son compatibles con el bloque y no se restauraron.');}catch(e){/* Sin borrador válido; no se sobrescribe aquí el almacenamiento. */}}

function toast(message){$('toast').textContent=message;$('toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('on'),2600);}
function idsFor(role){return state.selected.filter(id=>BY_ID[id].role===role);}
function resolved(role){const ids=idsFor(role);return ids.length===1?ids[0]:ids.includes(state.choices[role])?state.choices[role]:null;}
function conflicts(){return ['header','nav'].filter(role=>idsFor(role).length>1&&!resolved(role));}
function finalIds(){return Object.keys(ROLES).flatMap(role=>['header','nav'].includes(role)?[resolved(role)].filter(Boolean):idsFor(role));}
