/* Modo de la pantalla: «auto» sigue a la paleta o al fondo; «claro» y «oscuro» mandan sobre ellos. La variante oscura de una paleta clara conserva sus colores sobre un gris neutro. */
function darkVariant(P){return P&&P.dark?P:{id:(P?P.id:'base')+'-noche',name:(P?P.name:'Base')+' (noche)',dark:true,bg:'#161618',surface:'#222225',accent:P?P.accent:'#ff704b',accent2:P?P.accent2:'#ffb199',ink:'#f3f1ec',line:'#323236'};}
