let labConfig=null;
const stateLabels={default:'Normal',disabled:'Deshabilitado',loading:'Cargando',success:'Correcto',error:'Error',selected:'Seleccionado',original:'Original',outline:'Con borde',soft:'Suave',compact:'Compacta',horizontal:'Horizontal'};
function setupStateLab(block){const definition=TintaStates.info(block);$('stateLab').hidden=!definition;if(!definition){labConfig=null;return;}labConfig={...(state.ui[block.id]||{mode:'default',variant:'original'})};for(const [element,values,key] of [[$('labVariant'),definition.variants,'variant'],[$('labMode'),definition.modes,'mode']]){element.replaceChildren();values.forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=stateLabels[value]||value;element.appendChild(option);});element.value=labConfig[key];}$('labNote').textContent='Solo estás probando: no cambia tu selección ni los ajustes guardados. Las acciones son demostraciones locales, sin servicios.';}
