$('labVariant').addEventListener('change',ev=>{labConfig.variant=ev.target.value;refreshStateLab();});$('labMode').addEventListener('change',ev=>{labConfig.mode=ev.target.value;refreshStateLab();});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||!detailId||!labConfig)return;if(b.dataset.act==='lab-focus'){const shadow=$('detailStage').querySelector('.component-host').shadowRoot;const control=shadow.querySelector('input:not(:disabled),button:not(:disabled),a:not([aria-disabled=true])');if(control){control.focus();$('labNote').textContent='Foco dentro del componente. Usa Tab y Mayús+Tab para recorrerlo; Espacio o Enter para activar los controles.';}else $('labNote').textContent='Este estado no permite enfocar controles. Vuelve al estado Normal para probar el teclado.';}if(b.dataset.act==='lab-apply'){state.ui=TintaStates.normalize({...state.ui,[detailId]:{...labConfig}},BY_ID);state.composed=false;const persisted=save();if(state.page==='review')renderReview();$('componentCode').value=componentDocument();$('labNote').textContent=persisted?'Ajustes conservados en el borrador. Guardar o actualizar un proyecto conservará también esta variante y su estado inicial.':'Ajustes aplicados solo a esta sesión: no se pudo guardar en el navegador. Descarga el proyecto JSON para conservarlos.';toast(persisted?'Variante y estado conservados. Tu selección no cambió.':'Ajustes aplicados a esta sesión. No se pudieron guardar.');}if(b.dataset.act==='lab-reset'){delete state.ui[detailId];state.composed=false;save();if(state.page==='review')renderReview();setupStateLab(BY_ID[detailId]);refreshStateLab();$('componentCode').value=componentDocument();$('labNote').textContent='Variante y estado originales restaurados. Los textos, fotos y destinos se conservan.';}});

function componentDocument(){if(!detailId)return '';return '<!doctype html>\n<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(BY_ID[detailId].name)+'</title><style>body{margin:0;padding:24px;background:#f3f1ed}estilos-block{display:block;max-width:390px;margin:auto}</style></head><body>'+blockMarkup(BY_ID[detailId])+TintaStates.script()+'</body></html>';}
/* Imagen del componente (PNG/SVG): se mide fuera de pantalla con los ajustes actuales y se limpia antes de exportar. */
async function componentImage(kind){if(!detailId)return;const block=BY_ID[detailId],stage=document.createElement('div');stage.style.cssText='position:fixed;left:-99999px;top:0;width:340px;visibility:hidden';const host=makeBlock(block);stage.appendChild(host);document.body.appendChild(stage);const height=Math.ceil(host.getBoundingClientRect().height)||200,html=host.shadowRoot.innerHTML;stage.remove();const name=TintaImage.slug(block.metadata&&block.metadata.slug||block.name);try{const out=TintaImage.svg({shadowHtml:html,width:340,height});if(kind==='svg'){downloadBlob(new Blob([out.svg],{type:'image/svg+xml'}),name+'.svg');toast('SVG descargado.');return;}downloadBlob(await TintaImage.png(out),name+'.png');toast('PNG descargado.');}catch(e){toast(kind==='png'?'No se pudo crear el PNG en este navegador; prueba con SVG.':'No se pudo crear la imagen.');}}
