  if(action==='filter-family'&&detailId){state.interactive=false;state.family=BY_ID[detailId].metadata.family;state.filter='all';state.module='all';state.style='all';state.source='all';state.chosenOnly=false;state.query='';$('catalogSearch').value='';$('catalogSource').value='all';$('catalogModule').value='all';$('catalogStyle').value='all';$('detailDialog').close();go('explore');}
