function palImgOpen(file){if(!file)return;if(!/^image\/(png|jpe?g|webp)$/.test(file.type)){toast('Usa una imagen PNG, JPG o WebP.');return;}if(file.size>10*1024*1024){toast('La imagen pesa más de 10 MB. Usa una más pequeña.');return;}const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const k=96/Math.max(img.naturalWidth,img.naturalHeight,1),w=Math.max(1,Math.round(img.naturalWidth*Math.min(1,k))),h=Math.max(1,Math.round(img.naturalHeight*Math.min(1,k))),cv=document.createElement('canvas');cv.width=w;cv.height=h;const cx=cv.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0,w,h);let px;try{px=cx.getImageData(0,0,w,h).data;}catch(e){URL.revokeObjectURL(url);toast('No se pudo leer esa imagen.');return;}$('palImgPreview').src=url;palImg={mode:'auto',pix:px,res:null,url};$('palImgName').value=(file.name||'').replace(/\.[^.]+$/,'').replace(/[<>]/g,'').slice(0,40)||'Mi paleta';const d=$('paletteImgDialog');palImgPaint();if(!palImg.res){URL.revokeObjectURL(url);toast('Esa imagen no tiene colores que leer.');return;}if(!d.open)d.showModal();};img.onerror=()=>{URL.revokeObjectURL(url);toast('No se pudo abrir esa imagen.');};img.src=url;}
