function recMessages(list,kind){const ul=$('recMsg');ul.textContent='';list.forEach(t=>{const li=document.createElement('li');li.textContent=t;li.className=kind;ul.appendChild(li);});}
async function recCopy(text,note){try{if(!await copyToClipboard(text))throw Error();$('recCopyNote').textContent=note;return true;}catch(e){const p=$('recPrompt');p.hidden=false;p.value=text;p.focus();p.select();$('recCopyNote').textContent='Tu navegador no deja copiar solo: el texto está seleccionado, cópialo a mano.';return false;}}
function openReceta(){const d=$('recetaDialog');recAiNote();recChatsRender();recWaiting=false;$('recPaste').classList.remove('ready');$('recIdea').value=($('idea').value||state.brief||'').trim();$('recAnswer').value='';$('recPrompt').hidden=true;$('recFix').hidden=true;$('recMsg').textContent='';if(!d.open)d.showModal();}
let recLast=null;
async function recBuild(){const ans=$('recAnswer').value;if(!ans.trim()){recMessages(['Pega primero la respuesta del chat.'],'err');return;}const res=receta().parse(ans);recLast=res;if(!res.ok){recMessages(res.errors.concat(res.warnings),'err');$('recFix').hidden=false;return;}const idea=$('recIdea').value.trim();const r=res.recipe;if(idea)r.brief=idea;else if(!r.brief)r.brief=state.brief;const t=receta().toTemplate(r);t.fromRecipe=true;t.keepBrief=true;applyTemplate(t);if($('recetaDialog').open)$('recetaDialog').close();if(res.warnings.length)toast('Pantalla creada. Ajustes automáticos: '+res.warnings.length+'.');}
/* Conexión con una IA (tinta-ia.js): clave propia, lista real de modelos y prueba de cada uno; solo se usan los que responden. */
const iaStore={getItem:k=>{try{return localStorage.getItem(k);}catch(e){return null;}},setItem:(k,v)=>{try{localStorage.setItem(k,v);}catch(e){throw e;}}};
const ia=TintaIA.create({fetch:(u,i)=>nativeFetch(u,i)||fetch(u,i),storage:iaStore});
let iaLive=null,iaBusy=false,iaSel='groq';
function iaProv(){return ia.getProvider(iaSel);}
function iaSay(text,kind){const n=$('iaStatus');n.textContent=text||'';n.className='ia-status'+(kind?' '+kind:'');}
function iaChips(){const box=$('iaProviders');box.textContent='';ia.providers.forEach(p=>{const b=document.createElement('button');b.type='button';b.className='prov-chip';b.dataset.act='ia-provider';b.dataset.id=p.id;b.setAttribute('role','radio');b.setAttribute('aria-checked',String(p.id===iaSel));b.textContent=p.name.replace(/ \(compatible con OpenAI\)/,'');if(ia.cfgOf(p.id).models.length){const s=document.createElement('span');s.className='ok';s.textContent=' ✓';s.setAttribute('aria-label','conectado');b.appendChild(s);}box.appendChild(b);});}
function iaRender(){const def=iaProv(),cfg=ia.cfgOf(def.id);iaChips();$('iaTagline').textContent=def.tagline+(def.hint?' · '+def.hint:'');const a=$('iaKeyLink');a.hidden=!def.keyUrl;if(def.keyUrl)a.href=def.keyUrl;a.textContent=def.keyOptional?'Conseguir una clave (opcional) ↗':'Conseguir una clave ↗';$('iaBaseRow').hidden=!def.custom;$('iaBase').value=cfg.baseUrl||'';if(document.activeElement!==$('iaKey'))$('iaKey').value=cfg.apiKey||'';iaModels();const act=ia.active(),box=$('iaActive');box.hidden=!act;box.textContent=act?'✓ En uso: '+ia.getProvider(act.provider).name+' · '+act.model:'';}
function iaModels(){const def=iaProv(),cfg=ia.cfgOf(def.id),ul=$('iaModels');ul.textContent='';const rows=iaLive||new Map(Object.entries(cfg.checked||{}));const act=ia.active();[...rows.entries()].sort((x,y)=>(TintaIA.usable(y[1].verdict)-TintaIA.usable(x[1].verdict))||(x[1].ms-y[1].ms)).forEach(([m,r])=>{const li=document.createElement('li'),good=TintaIA.usable(r.verdict);li.className=good?'ok':'bad';const name=document.createElement('span');name.className='ia-name';name.textContent=(good?'✓ ':'✗ ')+m;const why=document.createElement('span');why.className='ia-why';why.textContent=(TintaIA.hint(r.status,r.detail)||TintaIA.MESSAGES[r.verdict])+(good?' · '+Math.round(r.ms)+' ms':'');li.append(name,why);if(good){const b=document.createElement('button');b.type='button';b.className='button light';b.dataset.act='ia-use';b.dataset.model=m;const on=act&&act.provider===def.id&&act.model===m;b.textContent=on?'✓ En uso':'Usar';b.setAttribute('aria-pressed',String(!!on));li.appendChild(b);}ul.appendChild(li);});}
function openIA(){const d=$('iaDialog'),act=ia.active();if(act)iaSel=act.provider;iaLive=null;iaSay('');iaRender();if(!d.open)d.showModal();}
async function iaConnect(){if(iaBusy)return;const def=iaProv(),key=$('iaKey').value.trim();if(!key&&!def.keyOptional){iaSay('Pega primero la clave.','err');return;}if(def.custom&&!TintaIA.safeBase($('iaBase').value)){iaSay('La dirección base debe empezar por https://.','err');return;}ia.setKey(def.id,key,def.custom?$('iaBase').value:undefined);iaBusy=true;iaLive=new Map();$('iaConnect').disabled=true;iaSay('Pidiendo la lista de modelos…','busy');iaModels();try{const r=await ia.connect(def.id,{onResult:(m,x)=>{iaLive.set(m,x);iaSay('Probando modelos… '+iaLive.size,'busy');iaModels();}});iaSay(r.good.length?r.good.length+' de '+r.tested+' modelos responden'+(r.total>r.tested?' (se probaron '+r.tested+' de '+r.total+')':'')+'. Elige uno con «Usar».':'Ningún modelo respondió'+(r.tested?' ('+r.tested+' probados)':'')+'. Revisa la clave o prueba otro proveedor.',r.good.length?'ok':'err');}catch(e){iaSay(e.message||'No se pudo conectar.','err');}finally{iaBusy=false;iaLive=null;$('iaConnect').disabled=false;iaRender();recAiNote();}}
function recAiNote(){const act=ia.active(),n=$('recAiNote');if(!n)return;n.textContent=act?'IA conectada: '+ia.getProvider(act.provider).name+' · '+act.model:'Aún no hay una IA conectada.';$('recIaBtn').textContent=act?'Cambiar de IA':'Conectar una IA';}
async function recAI(){const idea=$('recIdea').value.trim();if(!idea){recMessages(['Escribe primero tu idea.'],'err');return;}if(!ia.active()){openIA();return;}const btn=$('recAi');btn.disabled=true;recMessages(['Pidiendo el diseño a la IA…'],'warn');try{const prompt=receta().prompt(idea),opts={maxTokens:2048,temperature:.5};let text=await ia.chat([{role:'user',content:prompt}],opts),res=receta().parse(text);if(!res.ok){recMessages(['La primera respuesta no servía; se la devuelvo con las correcciones…'],'warn');text=await ia.chat([{role:'user',content:prompt},{role:'assistant',content:text},{role:'user',content:receta().fixPrompt(res)}],opts);res=receta().parse(text);}$('recAnswer').value=text;await recBuild();}catch(e){recMessages([e.message||'No se pudo hablar con la IA.'],'err');}finally{btn.disabled=false;}}
/* Equipo de diseño (tinta-equipo.js): ocho especialistas con trabajo real. Cada uno enseña lo que decidió midiendo la pantalla de verdad. */
let teamUi=null;
function teamEnv(){return {sectorOf:TintaSectors.detect,templates:TintaTemplates.LIST,problems:t=>TintaTemplates.problems(t,BY_ID),palettes:TintaPalettes.LIST,fonts:TintaFonts.LIST,backgrounds:TintaBackgrounds.LIST,roleOf:id=>BY_ID[id]&&BY_ID[id].role,byId:BY_ID,family:p=>TintaTaxonomy.paletteFamily(p)};}
/* Aplica la versión sin guardarla, la mide y deja todo como estaba. */
function teamMeasure(t){const snap=draftSnapshot(),idea=$('idea').value,sv=screenView;try{applyTemplate({...t},{silent:true});const screens=screensAvail().map(v=>TintaScreens.LABELS[v]||v),texts=Object.values(state.content).reduce((n,a)=>n+a.filter(Boolean).length,0);guardFixes=0;const html=exportHTML();return {screens,texts,fixes:guardFixes,kb:Math.max(1,Math.round(html.length/1024)),blocks:t.blocks.length,home:t.blocks.reduce((n,b)=>n+(b.repeat||1),0)};}finally{Object.assign(state,normalizedDraft(snap));state.composed=false;$('idea').value=idea;screenView=sv;}}
function teamReport(plan){const mA=teamMeasure(plan.A),mB=teamMeasure(plan.B),pa=TintaPalettes.get(plan.A.palette),pb=TintaPalettes.get(plan.B.palette),fa=TintaFonts.get(plan.A.font),list=mA.screens.slice(0,6).join(', ')+(mA.screens.length>6?'…':'');
const rep=[{out:plan.sector?'Sector: '+plan.sector.name+' · '+plan.affine+' plantillas afines':'No detecté un sector claro: partí de la plantilla más cercana'},{out:mA.screens.length+' pantallas: '+list},{work:'Eligiendo los '+mA.blocks+' bloques de «Inicio»',out:plan.A.name+': '+mA.blocks+' bloques'+(mA.home>mA.blocks?' ('+mA.home+' con copias)':'')+' en Inicio'},{out:'Paleta '+pa.name+' · letra '+(fa?fa.name:'Jakarta')+' · '+(pa.dark?'oscura':'clara')},{work:'Escribiendo '+mA.texts+' textos',out:mA.texts+' textos adaptados a tu idea'},{out:mA.fixes?mA.fixes+' ajustes de contraste · todo ≥ 4.5:1':'Todo cumple 4.5:1 sin tocar nada'},{out:mA.screens.length+' pantallas · '+mA.kb+' KB de HTML listo para exportar'},{out:'Revisó el trabajo y propone otra versión'}];
rep.metrics={A:mA.screens.length+' pantallas · paleta '+pa.name,B:mB.screens.length+' pantallas · '+(pb.dark?'oscura':'clara')+' · '+pb.name};return rep;}
async function teamAiTemplate(idea){if(!ia.active())return null;try{const prompt=receta().prompt(idea),o={maxTokens:2048,temperature:.5};let text=await ia.chat([{role:'user',content:prompt}],o),res=receta().parse(text);if(!res.ok){text=await ia.chat([{role:'user',content:prompt},{role:'assistant',content:text},{role:'user',content:receta().fixPrompt(res)}],o);res=receta().parse(text);}if(!res.ok)return null;const t=receta().toTemplate(res.recipe);t.name='Propuesta de tu IA';return t;}catch(e){return null;}}
let teamFromChat=false;
async function openTeam(idea0,aiTpl){const idea=(idea0||$('idea').value||state.brief||'').trim();if(!idea){toast('Escribe primero tu idea.');$('idea').focus();return;}if(idea0)$('idea').value=idea;const d=$('equipoDialog');if(!teamUi)teamUi=TintaEquipo.mount({dialog:d,palette:id=>TintaPalettes.get(id),close:()=>{if(teamMotorReq){const id=teamMotorReq;teamMotorReq=null;d.close();motorReply(id,false,'Cancelado');return;}d.close();if(teamFromChat){teamFromChat=false;openChat();}},apply:(t,mode)=>{if(teamMotorReq){const id=teamMotorReq;teamMotorReq=null;d.close();try{motorReply(id,true,{modo:['equipo','mezcla','critico'][mode],plantilla:t,...motorRender(t)});}catch(e){motorReply(id,false,e);}return;}teamFromChat=false;d.close();applyTemplate({...t,toast:'Pantalla creada con el equipo ('+['versión del equipo','mezcla','versión del Crítico'][mode]+')'});}});if(!d.open)d.showModal();const m1=d.querySelector('#eqM1');let ai=aiTpl||null;if(!ai&&ia.active()){if(m1)m1.textContent='Consultando a tu IA…';ai=await teamAiTemplate(idea);}const plan=TintaEquipo.plan(teamEnv(),idea,ai);teamUi.load(plan,teamReport(plan));}
/* Subir a GitHub (tinta-github.js): token propio, un solo commit con la app, el README y el archivo del proyecto. */
const gh=TintaGitHub.create({fetch:(u,i)=>nativeFetch(u,i)||fetch(u,i),storage:iaStore});
function ghReadme(){const idea=(state.brief||'Mi app').trim(),screens=screensAvail().map(v=>TintaScreens.LABELS[v]||v),pal=TintaPalettes.get(state.palette),font=TintaFonts.get(state.font),dark=wantDark(),P=effPalette?effPalette():null,line=(k,v)=>'- '+k+': `'+v+'`';
const tokens=P?['bg','surface','accent','accent2','ink','line'].filter(k=>P[k]).map(k=>line(k,P[k])).join('\n'):'';
return ['# '+idea.slice(0,80).replace(/[\r\n#]+/g,' '),'','> '+idea.replace(/[\r\n]+/g,' '),'','App diseñada con **Estilos Tinta**. Este repositorio tiene el diseño listo para abrir en el navegador.','','## Qué incluye','','- `index.html`: la app completa en un solo archivo, con todas las pantallas enlazadas.','- `tinta-proyecto.json`: el proyecto, para volver a abrirlo y seguir editando en Tinta («Mis proyectos» → importar).','- `README.md`: este archivo.','','## Pantallas','',screens.map(x=>'- '+x).join('\n'),'','## Diseño','','- Paleta: '+(pal?pal.name:'automática')+(dark?' (oscura)':''),'- Tipografía: '+(font?font.name:'la del sistema'),tokens?'\n'+tokens:'','','## Cómo verla','','Abre `index.html` en el navegador, o activa GitHub Pages en *Settings → Pages* eligiendo esta rama.','','## Para continuar con una IA de programación','','Pega esto en tu IA de código junto con `index.html`:','','> Convierte `index.html` en una app real (elige el framework que prefieras) manteniendo exactamente las pantallas, los textos, los colores y la tipografía de este diseño. No cambies el diseño; añade solo la lógica y los datos que falten.',''].join('\n');}
function githubFiles(){const name=(state.brief||'Mi pantalla').trim().slice(0,80)||'Mi pantalla';return [{path:'index.html',content:exportHTML()},{path:'README.md',content:ghReadme()},{path:'tinta-proyecto.json',content:JSON.stringify({format:'estilos-tinta-project',version:1,name,draft:draftSnapshot()},null,2)}];}
function ghStatus(t){$('ghStatus').textContent=t;}
function ghRepoParts(){const v=$('ghRepo').value.trim().replace(/^https?:\/\/github\.com\//i,'').replace(/\.git$/i,'').replace(/\/+$/,''),m=/^([^\/\s]+)\/([^\/\s]+)$/.exec(v);return m?{owner:m[1],repo:m[2]}:null;}
function openGH(){if(!state.composed||conflicts().length){toast('Primero crea tu pantalla.');return;}const d=$('ghDialog'),c=gh.load();$('ghToken').value=c.token||'';$('ghRepo').value=c.owner&&c.repo?c.owner+'/'+c.repo:'';$('ghBranch').value=c.branch||'';$('ghDir').value=c.dir||'';$('ghSteps').textContent='';$('ghResult').textContent='';ghStatus(c.token?'Token guardado en este dispositivo.':'');if(!d.open)d.showModal();}
async function ghVerify(){const tk=$('ghToken').value.trim();if(!tk){ghStatus('Pega primero el token.');return false;}gh.set({token:tk});ghStatus('Comprobando…');try{const v=await gh.verify(),dl=$('ghRepos');dl.textContent='';v.repos.forEach(r=>{const o=document.createElement('option');o.value=r.full;dl.appendChild(o);});ghStatus('Conectado como '+v.login+' · '+v.repos.length+' repositorio'+(v.repos.length===1?'':'s')+' con permiso de escritura.'+(v.repos.length===1&&!$('ghRepo').value?'.':''));if(v.repos.length===1&&!$('ghRepo').value)$('ghRepo').value=v.repos[0].full;return true;}catch(e){ghStatus(e.message);return false;}}
function ghLink(parent,text,href){const a=document.createElement('a');a.href=href;a.textContent=text;a.target='_blank';a.rel='noopener noreferrer';parent.appendChild(a);}
async function ghPush(){const tk=$('ghToken').value.trim(),rp=ghRepoParts();if(!tk){ghStatus('Pega primero el token.');return;}if(!rp){ghStatus('Escribe el repositorio como usuario/repositorio.');return;}gh.set({token:tk});const btn=$('ghPush'),steps=$('ghSteps'),res=$('ghResult');btn.disabled=true;res.textContent='';steps.textContent='';const log=t=>{steps.textContent='';const li=document.createElement('li');li.className='warn';li.textContent=t;steps.appendChild(li);};try{const files=githubFiles(),r=await gh.push({owner:rp.owner,repo:rp.repo,branch:$('ghBranch').value.trim(),dir:$('ghDir').value.trim(),files,message:'Proyecto creado con Estilos Tinta: '+(state.brief||'Mi app').trim().slice(0,80).replace(/[\r\n]+/g,' '),onStep:log});steps.textContent='';res.textContent='Listo: '+r.files+' archivos subidos a la rama «'+r.branch+'». ';ghLink(res,'Ver el commit',r.url);res.appendChild(document.createTextNode(' · '));ghLink(res,'Abrir el repositorio',r.repoUrl);if($('ghPages').checked){try{const pg=await gh.enablePages(rp.owner,rp.repo,r.branch);res.appendChild(document.createElement('br'));res.appendChild(document.createTextNode((pg.created?'Web activada: ':'La web ya estaba activada: ')+'puede tardar un par de minutos en aparecer. '));ghLink(res,pg.url,pg.url);}catch(e){res.appendChild(document.createElement('br'));res.appendChild(document.createTextNode('No pude activar la web: '+e.message+' (necesita el permiso Pages: Read and write; también puedes activarla en Settings → Pages).'));}}ghStatus('');}catch(e){steps.textContent='';ghStatus(e.message);}finally{btn.disabled=false;}}
/* Lanzadores a chats web: copia el prompt y abre el chat en el navegador (donde ya tienes la sesión). Luego «Pegar la respuesta copiada y crear». */
const CHATS=[{id:'chatgpt',name:'ChatGPT',url:'https://chatgpt.com/'},{id:'claude',name:'Claude',url:'https://claude.ai/new'},{id:'gemini',name:'Gemini',url:'https://gemini.google.com/app'},{id:'glm',name:'GLM',url:'https://chat.z.ai/'},{id:'deepseek',name:'DeepSeek',url:'https://chat.deepseek.com/'},{id:'kimi',name:'Kimi',url:'https://www.kimi.com/'}];
let recWaiting=false;
function recChatsRender(){const box=$('recChats');if(!box||box.dataset.ready)return;box.dataset.ready='1';CHATS.forEach(c=>{const b=document.createElement('button');b.type='button';b.className='button light';b.dataset.act='rec-open';b.dataset.chat=c.id;b.textContent=c.name+' ↗';b.setAttribute('aria-label','Copiar el prompt y abrir '+c.name);box.appendChild(b);});}
async function recOpenChat(id){const c=CHATS.find(x=>x.id===id);if(!c)return;if(!$('recIdea').value.trim()){recMessages(['Escribe primero tu idea.'],'err');return;}const copied=await recCopy(receta().prompt($('recIdea').value),'Prompt copiado. Pégalo en '+c.name+' y, cuando responda, copia su respuesta y vuelve aquí.');recWaiting=true;window.open(c.url,'_blank','noopener,noreferrer');if(!copied)$('recCopyNote').textContent+=' (Ábrelo y pega el texto seleccionado.)';}
async function recPaste(){let text='';try{const nat=nativeRead();if(nat!==null)text=nat;else{if(!navigator.clipboard||!navigator.clipboard.readText)throw Error();text=await navigator.clipboard.readText();}}catch(e){$('recAnswer').focus();recMessages(['Tu navegador no deja leer lo copiado. Mantén pulsado en el recuadro de la respuesta, elige «Pegar» y pulsa «Crear mi pantalla».'],'warn');return;}if(!text.trim()){recMessages(['No hay nada copiado todavía. Copia la respuesta del chat y vuelve a pulsar.'],'err');return;}$('recAnswer').value=text;recWaiting=false;await recBuild();}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'||!recWaiting||!$('recetaDialog').open)return;$('recPaste').classList.add('ready');$('recCopyNote').textContent='¿Ya tienes la respuesta? Cópiala en el chat y pulsa «Pegar la respuesta copiada y crear».';});
/* Chat de diseño: eliges el modelo, hablas, y al pedir una app sale la pantalla del equipo construyéndola. */
const chat=TintaChat.create({storage:iaStore});
let chatBusy=false;
const CHAT_HELLO='¡Hola! Cuéntame qué app o pantalla quieres y la preparo con el equipo. También puedes pedirme cambios sobre lo que ya tienes («hazla oscura», «añade un carrito»).';
const CHAT_IDEAS=['Una app para mi cafetería con pedidos','Mis finanzas personales con gastos y ahorro','Una app de rutinas para el gimnasio'];
function chatModels(){const out=[];ia.providers.forEach(p=>ia.cfgOf(p.id).models.forEach(m=>out.push({provider:p.id,model:m,label:p.name+' · '+m})));return out;}
function chatRenderModels(){const sel=$('chatModel'),list=chatModels(),act=ia.active();sel.textContent='';if(!list.length){const o=document.createElement('option');o.textContent='Sin modelos: conecta una IA';o.value='';sel.appendChild(o);sel.disabled=true;return;}sel.disabled=false;list.forEach(x=>{const o=document.createElement('option');o.value=x.provider+'|'+x.model;o.textContent=x.label;if(act&&act.provider===x.provider&&act.model===x.model)o.selected=true;sel.appendChild(o);});}
function chatCurrent(){if(!state.selected.length)return '';const P=TintaPalettes.get(state.palette);return state.selected.map(id=>id+(state.repeat[id]>1?'×'+state.repeat[id]:'')).join(', ')+(P?'; paleta '+P.id:'')+(state.mode?'; modo '+(state.mode==='dark'?'oscuro':'claro'):'');}
function chatVisible(text){return String(text).replace(/```[\s\S]*?```/g,'').trim();}
function chatBubble(cls,text){const d=document.createElement('div');d.className='msg '+cls;d.textContent=text;return d;}
function chatRender(){const log=$('chatLog');log.textContent='';const all=chat.all();log.appendChild(chatBubble('bot',CHAT_HELLO));if(!all.length){const box=document.createElement('div');box.className='chat-ideas';CHAT_IDEAS.forEach(t=>{const b=document.createElement('button');b.type='button';b.className='prov-chip';b.dataset.act='chat-idea';b.textContent=t;box.appendChild(b);});log.appendChild(box);}
all.forEach((m,i)=>{if(m.role==='user'){log.appendChild(chatBubble('user',m.content));return;}const res=receta().parse(m.content),text=chatVisible(m.content)||(res.ok?'Te propongo esta pantalla.':'');if(text)log.appendChild(chatBubble('bot',text));if(res.ok){const r=res.recipe,card=document.createElement('div');card.className='recipe-card';const P=r.palette&&TintaPalettes.get(r.palette),h=document.createElement('b');h.textContent='Pantalla propuesta';const info=document.createElement('span');info.textContent=r.blocks.length+' bloques'+(P?' · paleta '+P.name:'')+(r.mode==='dark'?' · oscura':'');const b=document.createElement('button');b.type='button';b.className='button coral';b.dataset.act='chat-team';b.dataset.i=String(i);b.textContent='Verla con el equipo';card.append(h,info,b);log.appendChild(card);}});
if(chatBusy){const t=chatBubble('bot typing','');t.innerHTML='<i></i><i></i><i></i>';t.setAttribute('aria-label','Escribiendo');log.appendChild(t);}log.scrollTop=log.scrollHeight;}
function chatError(msg){const log=$('chatLog');const d=chatBubble('err',msg||'No se pudo hablar con la IA.');const b=document.createElement('button');b.type='button';b.className='button light';b.dataset.act='chat-retry';b.textContent='Reintentar';d.appendChild(b);log.appendChild(d);log.scrollTop=log.scrollHeight;}
function openChat(){const d=$('chatDialog');chatRenderModels();chatRender();if(!d.open)d.showModal();$('chatInput').focus();}
function chatToTeam(reply){const res=receta().parse(reply);if(!res.ok)return;const r=res.recipe,t=receta().toTemplate(r);t.name='Propuesta del chat';const idea=(r.brief||chat.lastIdea()||'Mi app').slice(0,200);$('chatDialog').close();teamFromChat=true;openTeam(idea,t);}
async function chatAsk(){if(chatBusy)return;if(!ia.active()){chatRender();chatError('Conecta primero una IA: pulsa «⚙ Claves».');return;}chatBusy=true;$('chatSend').disabled=true;chatRender();try{const reply=await ia.chat(chat.forModel(receta().chatSystem(chat.lastIdea(),chatCurrent())),{maxTokens:2048,temperature:.6});chat.add('assistant',reply);chatBusy=false;chatRender();const res=receta().parse(reply);if(res.ok)setTimeout(()=>{if($('chatDialog').open)chatToTeam(reply);},700);}catch(e){chatBusy=false;chatRender();chatError(e.message);}finally{chatBusy=false;$('chatSend').disabled=false;}}
function chatSend(text){text=String(text||'').trim();if(!text||chatBusy)return;chat.add('user',text);$('chatInput').value='';chatAsk();}
/* Motor para otras apps (FORJA). Con ?motor=1 dentro de un iframe del MISMO origen, la página atiende peticiones por
   postMessage: instrucciones para el modelo, leer su respuesta, dibujar la app completa y abrir al equipo de agentes.
   Nunca guarda nada: aplica en silencio, mide/exporta y deja el estado como estaba. Solo responde a su ventana madre. */
const MOTOR_API=1,MOTOR=(()=>{try{return window.parent!==window&&new URLSearchParams(location.search).get('motor')==='1';}catch(e){return false;}})();
let teamMotorReq=null;
function motorReply(id,ok,data){try{window.parent.postMessage(ok?{tipo:'tinta:respuesta',id,ok:true,datos:data}:{tipo:'tinta:respuesta',id,ok:false,error:String(data&&data.message||data||'Error')},location.origin);}catch(e){/* la ventana madre ya no está */}}
function motorTemplate(d){let t=d.plantilla&&typeof d.plantilla==='object'?{...d.plantilla}:null;if(!t&&d.receta)t=receta().toTemplate(d.receta);if(!t||!Array.isArray(t.blocks))throw Error('Falta la receta o la plantilla.');const probs=TintaTemplates.problems(t,BY_ID);if(probs.length)throw Error('La receta no es válida: '+probs.join(', '));t.fromRecipe=true;t.keepBrief=true;if(d.idea)t.brief=String(d.idea).slice(0,200);return t;}
function motorRender(t){const snap=draftSnapshot(),idea=$('idea').value,sv=screenView,comp=state.composed;try{applyTemplate({...t},{silent:true});state.composed=true;const html=exportHTML(),pantallas=(multiOn()?screensAvail():['inicio']).map(v=>({id:v,nombre:TintaScreens.LABELS[v]||v}));return {html,pantallas,borrador:draftSnapshot()};}finally{Object.assign(state,normalizedDraft(snap));state.composed=comp;$('idea').value=idea;screenView=sv;}}
if(MOTOR){document.documentElement.classList.add('tinta-motor');
window.addEventListener('message',ev=>{if(ev.source!==window.parent||ev.origin!==location.origin)return;const m=ev.data;if(!m||m.tipo!=='tinta:pedir'||typeof m.id!=='number')return;const d=m.datos||{};try{
if(m.accion==='ping')return motorReply(m.id,true,{api:MOTOR_API,version:APP_VERSION,bloques:CATALOG.length,plantillas:TintaTemplates.LIST.length});
if(m.accion==='instrucciones'){const idea=String(d.idea||'').slice(0,1500);return motorReply(m.id,true,{sistema:receta().chatSystem(idea,String(d.actual||'').slice(0,600)),prompt:receta().prompt(idea)});}
if(m.accion==='leer'){const r=receta().parse(String(d.texto||''));return motorReply(m.id,true,{ok:r.ok,errores:r.errors,avisos:r.warnings,receta:r.recipe,correccion:r.ok?'':receta().fixPrompt(r)});}
if(m.accion==='dibujar')return motorReply(m.id,true,motorRender(motorTemplate(d)));
if(m.accion==='equipo'){const t=motorTemplate(d);if(teamMotorReq)motorReply(teamMotorReq,false,'Sustituido por otra petición');teamMotorReq=m.id;t.name=String(d.nombre||'Propuesta de tu IA').slice(0,60);openTeam(t.brief||String(d.idea||'Mi app'),t);return;}
motorReply(m.id,false,'Acción desconocida: '+String(m.accion).slice(0,40));}catch(e){motorReply(m.id,false,e);}});
$('equipoDialog').addEventListener('close',()=>setTimeout(()=>{if(teamMotorReq){const id=teamMotorReq;teamMotorReq=null;motorReply(id,false,'Cancelado');}},0));
window.parent.postMessage({tipo:'tinta:listo',api:MOTOR_API},location.origin);}
function usePalette(id){const P=TintaPalettes.get(id);if(!P)return;state.palette=state.palette===id?null:id;state.composed=false;save('Paleta «'+P.name+'»');paintPalettes();paintVisuals();if(state.page==='review')renderReview();else renderPhone();toast(state.palette?'Paleta «'+P.name+'» aplicada. Los estilos que ajustaste a mano se respetan.':'Paleta quitada.');}
/* Mis estilos: editor con vista previa en vivo. Guarda en el almacén de la biblioteca y recarga para reconstruir el catálogo. */
let styleEditingId=null,styleDeleteArmed=false;
const msF=id=>$(id);
function msFillTabs(current){const sel=msF('msTab');sel.replaceChildren();Object.keys(TintaMyStyles.TABS).forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;if(t===current)o.selected=true;sel.appendChild(o);});}
function msFillVariants(tab,current){const sel=msF('msVariant');sel.replaceChildren();const base=document.createElement('option');base.value='';base.textContent='Diseño por defecto de la categoría';sel.appendChild(base);TintaMyStyles.variants(tab,D).forEach(k=>{const o=document.createElement('option');o.value=k;o.textContent=k.split('.')[1];if(k===current)o.selected=true;sel.appendChild(o);});}
function msRead(){return {id:styleEditingId||undefined,name:msF('msName').value,tab:msF('msTab').value,v:msF('msVariant').value,colors:msF('msColors').value,radius:msF('msRadius').value,mode:msF('msMode').value,desc:msF('msDesc').value,tip:msF('msTip').value,code:msF('msCode').value};}
function msPreview(){const r=TintaMyStyles.normalize({...msRead(),name:msF('msName').value||'Vista previa'},D),host=$('stylePreview');if(r.error){$('styleMessage').textContent=r.error;return;}$('styleMessage').textContent='';try{const parts=TintaLibraryTools.preview(r.entry);host.style.background=r.entry.mode==='dark'?'#16181d':'#f5f4ef';const sh=host.shadowRoot||host.attachShadow({mode:'open'});sh.innerHTML='<style>'+BASE+parts.css+'</style>'+parts.html;}catch(e){$('styleMessage').textContent='No se pudo dibujar este código: revisa el HTML y el CSS.';}}
function openStyleDialog(raw,isNew){styleEditingId=raw&&!isNew?raw.id:null;const e=raw||{tab:'Tarjetas',colors:['#ff704b','#ffffff','#242421'],radius:'16',mode:'light'};$('styleTitle').textContent=styleEditingId?'Editar mi estilo':'Crear mi estilo';msF('msName').value=raw?(isNew?(raw.name+' (mío)').slice(0,80):raw.name):'';msFillTabs(TintaMyStyles.TABS[e.tab]?e.tab:'Tarjetas');msFillVariants(msF('msTab').value,e.v||'');msF('msColors').value=(Array.isArray(e.colors)?e.colors:['#ff704b']).join(', ');msF('msRadius').value=String(e.radius||'16');msF('msMode').value=e.mode==='dark'?'dark':'light';msF('msDesc').value=e.desc||'';msF('msTip').value=e.tip||'';msF('msCode').value=e.code||'';$('styleMessage').textContent='';if($('detailDialog').open)$('detailDialog').close();$('styleDialog').showModal();msPreview();msF('msName').focus();}
$('backupFile').addEventListener('change',ev=>readBackupFile(ev.target.files&&ev.target.files[0]));
$('styleForm').addEventListener('input',ev=>{if(ev.target.id==='msTab')msFillVariants(msF('msTab').value,'');msPreview();});
$('styleForm').addEventListener('submit',ev=>{ev.preventDefault();const out=TintaMyStyles.save(msRead(),D);if(out.error){$('styleMessage').textContent=out.error;return;}try{sessionStorage.setItem('estilos-mine-open',out.entry.id);}catch(e){/* sin sessionStorage */}$('styleDialog').close();toast(out.updated?'Estilo actualizado.':'Estilo guardado en «Mis estilos».');setTimeout(()=>{location.hash='#bloques/guardados/mios';location.reload();},350);});
function mineBlock(){return detailId&&BY_ID[detailId]&&BY_ID[detailId].raw?BY_ID[detailId]:null;}
function updateMineButtons(){const b=detailId&&BY_ID[detailId];$('detailMine').hidden=!(b&&b.raw);$('editStyle').hidden=!(b&&b.mine);$('deleteStyle').hidden=!(b&&b.mine);styleDeleteArmed=false;$('deleteStyle').textContent='Eliminar mi estilo';}
function deleteMyStyle(){const b=mineBlock();if(!b||!b.mine)return;if(!styleDeleteArmed){styleDeleteArmed=true;$('deleteStyle').textContent='¿Seguro? Pulsa otra vez para eliminar';return;}const out=TintaMyStyles.remove(b.raw.id);if(out.error){toast(out.error);return;}try{sessionStorage.setItem('estilos-mine-open','deleted');}catch(e){}toast('Estilo eliminado.');setTimeout(()=>{location.hash='#bloques/guardados/mios';location.reload();},350);}
/* Copia de seguridad completa: descarga todo y restaura sin borrar ni pisar nada (añade copias nuevas). */
const lsStore={get:k=>{try{return TintaStore.unpackText(localStorage.getItem(k));}catch(e){return null;}},set:(k,v)=>localStorage.setItem(k,TintaStore.packText(v))};
/* Si IndexedDB falla al guardar una foto, el borrador y los proyectos vuelven a guardarse con las fotos dentro del texto. */
TintaStore.onChange=()=>{try{localStorage.setItem(STORE,TintaStore.packText(JSON.stringify(draftSnapshot())));const l=readTintaProjects();if(l)writeTintaProjects(l);}catch(e){}};
let backupPending=null;
function backupLines(s){const l=[];const n=(c,one,many)=>{if(c)l.push(c+' '+(c===1?one:many));};n(s.projects,'proyecto de Tinta','proyectos de Tinta');n(s.styles,'estilo propio','estilos propios');n(s.favs,'favorito','favoritos');n(s.recent,'reciente','recientes');n(s.studioProjects,'proyecto del Editor','proyectos del Editor');if(s.draft)l.push('tu pantalla de trabajo');if(s.theme)l.push('tu tema');if(s.builder)l.push('el constructor antiguo');return l;}
function backupMsg(t){$('backupMessage').textContent=t;}
function openBackup(){backupPending=null;$('backupFile').value='';$('backupPreview').hidden=true;backupMsg('');const now=TintaBackup.inspect(JSON.stringify(TintaBackup.create(lsStore,typeof APP_VERSION==='string'?APP_VERSION:'')));const l=backupLines(now.summary);$('backupNow').textContent=l.length?'Ahora mismo tienes: '+l.join(', ')+'.':'Todavía no hay nada guardado que copiar.';$('backupDialog').showModal();}
function downloadBackup(){const text=JSON.stringify(TintaBackup.create(lsStore,typeof APP_VERSION==='string'?APP_VERSION:'')),d=new Date(),name='estilos-copia-'+d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')+'.json';downloadText(text,name,'application/json');backupMsg('Copia descargada ('+Math.max(1,Math.round(text.length/1024))+' KB). Guárdala en un lugar seguro.');}
async function readBackupFile(file){backupPending=null;$('backupPreview').hidden=true;if(!file)return;if(file.size>TintaBackup.MAX_BYTES){backupMsg('El archivo pesa más de 8 MB: no parece una copia de Estilos.');return;}try{const out=TintaBackup.inspect(await file.text());const l=backupLines(out.summary);if(!l.length){backupMsg('La copia no contiene nada que añadir.');return;}backupPending=out;$('backupList').replaceChildren(...l.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('backupPreview').hidden=false;backupMsg(out.exported?'Copia del '+out.exported.slice(0,10)+'. Revisa y pulsa «Añadir».':'Revisa y pulsa «Añadir».');}catch(e){backupMsg(e.message);}}
function applyBackup(){if(!backupPending)return;let r;try{r=TintaBackup.merge(backupPending.data,lsStore,{normalizeStyle:raw=>TintaMyStyles.normalize(raw,D)});}catch(e){backupMsg('No se pudo restaurar: '+(e.name==='QuotaExceededError'?'el almacenamiento del navegador está lleno.':e.message));return;}try{sessionStorage.setItem('estilos-backup-report',JSON.stringify(r));}catch(e){/* sin sessionStorage */}$('backupDialog').close();setTimeout(()=>{location.hash='#bloques/guardados/mios';location.reload();},200);}
/* ───── Todas las pantallas de la app ───── */
let screenView='inicio',navMap=[];
function multiOn(){return !!state.multi&&!!resolved('nav')&&!!TintaSectors.detect(state.brief);}
function navDescriptors(block){const t=document.createElement('template');t.innerHTML=editedBlock(block).html;return [...t.content.querySelectorAll('button,a')].map(b=>({text:b.textContent,aria:b.getAttribute('aria-label'),cls:b.className}));}
function screenPlan(){const cardList=idsFor('cards'),cardId=cardList[cardList.length-1]||'c-coral',headerId=resolved('header')||idsFor('header')[0]||'h-minimal';return TintaScreens.plan({headerId:BY_ID[headerId]?headerId:null,plainHeaderId:BY_ID['h-minimal']?'h-minimal':null,cardId:BY_ID[cardId]?cardId:null,actionId:idsFor('actions')[0]||null,hasList:!!BY_ID['lib-lis-1'],avatarId:idsFor('avatars')[0]||(BY_ID['av-perfil']?'av-perfil':(BY_ID['lib-ava-3']?'lib-ava-3':null))});}
function screensAvail(){const nid=resolved('nav');if(!nid)return ['inicio'];navMap=TintaScreens.mapNav(navDescriptors(BY_ID[nid]));const plan=screenPlan();return ['inicio',...new Set(navMap.filter(v=>v&&v!=='inicio'&&plan[v]&&plan[v].length)),...flowsOn()];}
/* Pantallas de recorrido de esta app: las que elegiste (por defecto, todas las que tienen sentido en tu sector). */
function flowsAll(){const sector=TintaSectors.detect(state.brief);return sector?TintaScreens.flowsFor(sector.id).filter(f=>BY_ID['f-'+f]):[];}
function flowsOn(){const all=flowsAll();return state.flows?all.filter(f=>state.flows.includes(f)):all;}
function flowForced(flow,sectorId){const S=TintaSectors.SECTORS.find(x=>x.id===sectorId);if(!S||typeof TINTA_FLOWS==='undefined')return undefined;const out=contentModel({html:TINTA_FLOWS.html(flow,S,appName(sectorId))}).fields.map(f=>String(f.value).slice(0,500));if(['detalle','bienvenida'].includes(flow)){const k=flow==='detalle'?0:1,a=artFor('f-'+flow,k,sectorId)||artFor('f-'+flow,k+1,sectorId);if(a)out.art=a;}return out;}
function sectorScreens(sectorId){return TintaSectors.SECTORS.find(x=>x.id===sectorId).screen;}
/* La marca genérica «studio» de las cabeceras sencillas se sustituye por el nombre de tu app. */
function brandFix(fields,out,sectorId){return out.map((v,i)=>fields[i]&&fields[i].label==='Texto'&&/^studio$/i.test(String(fields[i].value).trim())?appName(sectorId):v);}
/* Nombre de la app: lo que va antes de «:» o «—» en tu idea («Rumbo: una app de viajes…»); si no, el nombre del sector. */
function appName(sectorId){const m=/^\s*([\p{L}\p{N}][\p{L}\p{N} ]{1,17})\s*[:\-–—]/u.exec(state.brief||'');if(m)return m[1].trim();const n={comida:'Sabor',tienda:'Tienda',finanzas:'Finanzas',fitness:'Fitness',viajes:'Viajes',salud:'Salud',musica:'Música',educacion:'Aprende'};return n[sectorId]||'App';}
function headerForced(id,v,sectorId){const fields=contentModel(BY_ID[id]).fields,out=(TintaSectors.fill(sectorId,fields,{offset:1,role:'header'})||[]).map((x,i)=>x||fields[i].value),S=sectorScreens(sectorId),ti=fields.findIndex(f=>f.label==='Título');if(ti>=0)out[ti]=S[v]||out[ti];const texts=fields.map((f,i)=>i).filter(i=>i!==ti&&['Destacado','Nota','Texto'].includes(fields[i].label)&&String(fields[i].value).length>=10);if(texts.length){out[texts[0]]=S['sub_'+v]||out[texts[0]];if(v!=='explorar'&&v!=='inicio')texts.slice(1).forEach(i=>{out[i]=' ';});}fields.forEach((f,i)=>{if(f.label==='Texto'&&/^studio$/i.test(String(f.value).trim()))out[i]=appName(sectorId);});return out.map(x=>String(x).slice(0,500));}
function actionForced(id,v,sectorId){const fields=contentModel(BY_ID[id]).fields,out=(TintaSectors.fill(sectorId,fields,{offset:0})||[]).map((x,i)=>x||fields[i].value),t=TintaScreens.ACTION_TEXT[v],ai=fields.findIndex(f=>f.label==='Acción');if(t&&ai>=0)out[ai]=t;return out.map(x=>String(x).slice(0,500));}
function generatedItems(v){const sector=TintaSectors.detect(state.brief);if(!sector)return [];if(TintaScreens.FLOWS.includes(v))return BY_ID['f-'+v]?[{id:'f-'+v,forced:flowForced(v,sector.id)}]:[];return (screenPlan()[v]||[]).filter(it=>BY_ID[it.id]).flatMap(it=>{if(it.role==='header')return [{id:it.id,forced:headerForced(it.id,v,sector.id)}];if(it.role==='cards')return Array.from({length:it.repeat},(_,i)=>({id:it.id,forced:copyValues(it.id,i+it.offset,sector.id)}));if(it.role==='actions')return [{id:it.id,forced:actionForced(it.id,v,sector.id)}];if(it.role==='avatars')return [{id:it.id,forced:copyValues(it.id,0,sector.id)}];if(it.role==='list'){const f=contentModel(BY_ID[it.id]).fields,rows=TintaSectors.SECTORS.find(x=>x.id===sector.id).profile;return [{id:it.id,forced:f.length>=4?f.map((x,i)=>(rows[i]||x.value)):undefined}];}return [{id:it.id,forced:undefined}];});}
function homeItems(){return finalIds().filter(id=>BY_ID[id].role!=='nav').flatMap(id=>blockCopies(id).map(forced=>({id,forced})));}
function itemsFor(v){return v==='inicio'||!multiOn()?homeItems():generatedItems(v);}
let screenTrail=[];function setScreenView(v){if(v!==screenView)screenTrail.push(screenView);screenTrail=screenTrail.slice(-20);screenView=v;renderPhone();}
function phoneGo(target,avail){if(target==='back'){const prev=screenTrail.pop();screenView=prev&&avail.includes(prev)?prev:'inicio';renderPhone();return;}setScreenView(TintaScreens.resolve(target,avail));}
function paintScreens(){const on=multiOn(),tabs=$('screenTabs'),avail=on?screensAvail():['inicio'];const fp=$('flowPicks');if(fp){const all=on?flowsAll():[];fp.hidden=!all.length;const list=$('flowList');list.replaceChildren();const sel=flowsOn();all.forEach(f=>{const l=document.createElement('label');l.className='flow-pick';const i=document.createElement('input');i.type='checkbox';i.dataset.flow=f;i.checked=sel.includes(f);const t=document.createElement('span');t.textContent=TintaScreens.LABELS[f];l.append(i,t);list.appendChild(l);});}const tog=$('multiToggle');if(tog)tog.checked=!!state.multi;if(!tabs)return;tabs.hidden=!(on&&avail.length>1);tabs.replaceChildren();if(!tabs.hidden)avail.forEach(v=>{const b=document.createElement('button');b.type='button';b.dataset.act='view-screen';b.dataset.id=v;b.append(screenThumb(v),document.createTextNode(TintaScreens.LABELS[v]));b.setAttribute('aria-pressed',String(v===screenView));tabs.appendChild(b);});const cur=tabs.querySelector('[aria-pressed=true]');if(cur&&tabs.scrollWidth>tabs.clientWidth)tabs.scrollLeft=Math.max(0,cur.offsetLeft-tabs.clientWidth/2+cur.offsetWidth/2);}
/* Miniatura de cada pantalla (tira de la vista previa): los mismos bloques, a escala y sin interacción.
   Se guardan mientras el diseño no cambie, para no volver a pintarlas al navegar. */
const thumbCache={key:'',nodes:{}};
function screenThumb(v){const key=JSON.stringify(draftSnapshot());if(thumbCache.key!==key){thumbCache.key=key;thumbCache.nodes={};}if(!thumbCache.nodes[v]){const box=document.createElement('span');box.className='tab-thumb';box.setAttribute('aria-hidden','true');box.inert=true;const inner=document.createElement('div');inner.style.cssText='position:absolute;left:0;top:0;width:390px;min-height:620px;display:grid;gap:16px;align-content:start;padding:28px 17px;box-sizing:border-box;transform:scale(.1487);transform-origin:0 0;pointer-events:none;background:'+(paletteBg()||'#f5f4ef');inScreen(()=>itemsFor(v).slice(0,5).forEach(it=>inner.appendChild(makeBlock(BY_ID[it.id],compUI(it.id),undefined,undefined,it.forced))));/* raíz cerrada: es solo un dibujo, no forma parte de la página */box.attachShadow({mode:'closed'}).appendChild(inner);thumbCache.nodes[v]=box;}return thumbCache.nodes[v];}
function renderPhone(){return inScreen(renderPhoneNow);}
