function readMediaForm(){const next=JSON.parse(JSON.stringify(mediaDraft));$('mediaFields').querySelectorAll('[data-media-image]').forEach(input=>{const i=+input.dataset.mediaImage;const previous=next.images[i];const src=input.value.trim()||(previous&&previous.src.startsWith('data:')?previous.src:'');const alt=$('mediaFields').querySelector('[data-media-alt="'+i+'"]').value.slice(0,200);next.images[i]=src?{src,alt}:null;});$('mediaFields').querySelectorAll('[data-media-link]').forEach(input=>next.links[+input.dataset.mediaLink]=input.value.trim()||null);return next;}
$('mediaFields').addEventListener('change',async ev=>{const input=ev.target.closest('[data-media-file]');if(!input||!input.files[0])return;const epoch=mediaEpoch,index=+input.dataset.mediaFile;if(mediaBusy)return;mediaBusy++;$('mediaFields').inert=true;$('applyMedia').disabled=true;$('mediaMessage').textContent='Preparando la foto…';try{const current=readMediaForm();const src=await TintaAssets.compress(input.files[0]);if(epoch!==mediaEpoch||!$('mediaDialog').open)return;current.images[index]={src,alt:current.images[index]&&current.images[index].alt||''};mediaDraft=current;renderMediaFields();$('mediaMessage').textContent='Foto lista. Pulsa Aplicar para conservarla.';}catch(e){if(epoch===mediaEpoch)$('mediaMessage').textContent=e.message;}finally{if(epoch===mediaEpoch){mediaBusy=Math.max(0,mediaBusy-1);$('mediaFields').inert=!!mediaBusy;$('applyMedia').disabled=!!mediaBusy;}}});
