document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act;if(act==='edit-media')openMedia(b.dataset.id);if(act==='close-media')$('mediaDialog').close();if(act==='reset-media-image'){mediaDraft=readMediaForm();mediaDraft.images[+b.dataset.index]=null;renderMediaFields();$('mediaMessage').textContent='Imagen original preparada. Pulsa Aplicar para conservar el cambio.';}if(act==='reset-media'){delete state.assets[mediaId];state.composed=false;save();renderReview();$('mediaDialog').close();toast('Imágenes y destinos originales restaurados.');}});

// Edición de contenido: nodos de texto, nunca HTML proporcionado por el usuario.
function contentModel(block){const root=document.createElement('template');root.innerHTML=block.html;const fields=[];const walk=document.createTreeWalker(root.content,NodeFilter.SHOW_TEXT);let node;while((node=walk.nextNode())){if(node.textContent.trim()&&/[\p{L}\p{N}]/u.test(node.textContent)&&!node.parentElement.closest('svg,style,script')){const target=node;const parent=node.parentElement;const label=parent.closest('button,a')?'Acción':parent.closest('h1,h2,h3,h4,h5,h6')?'Título':parent.closest('small')?'Nota':parent.closest('b,strong')?'Destacado':'Texto';fields.push({value:node.textContent.trim(),label,set:v=>{target.textContent=v;}});}}root.content.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>fields.push({value:el.getAttribute('placeholder'),label:'Placeholder',set:v=>el.setAttribute('placeholder',v)}));return {root,fields:fields.slice(0,200)};}
/* Imagen de la tarjeta: sustituye la ilustración (.media>svg) por la de la copia; una foto tuya (assets) siempre manda. */
function withArt(block,svg){if(!svg)return block;const t=document.createElement('template');t.innerHTML=block.html;const olds=[...t.content.querySelectorAll('.media>svg,.av>svg')];if(!olds.length)return block;const list=Array.isArray(svg)?svg:[svg];olds.forEach((old,k)=>{const n=document.createElement('template');n.innerHTML=list[Math.min(k,list.length-1)];const neu=n.content.firstElementChild;if(neu)old.replaceWith(neu);});return {...block,html:t.innerHTML};}
function editedBlock(block,forced){const values=forced&&!forced.stateOnly?forced:state.content[block.id],art=forced&&forced.art;if(!values)return TintaAssets.apply(withArt(block,art),state.assets[block.id]);const model=contentModel(block);model.fields.forEach((f,i)=>{if(typeof values[i]==='string')f.set(values[i]);});return TintaAssets.apply(withArt({...block,html:model.root.innerHTML},art),state.assets[block.id]);}
function normalizedDraft(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.selected))throw Error('El archivo no contiene una selección de Tinta válida.');const selected=[...new Set(raw.selected.filter(id=>typeof id==='string'))];if(selected.length>CATALOG.length||selected.some(id=>!Object.hasOwn(BY_ID,id)))throw Error('Este proyecto usa bloques que no están en tu biblioteca actual. Recupera esos diseños antes de abrirlo.');const choices={header:null,nav:null};['header','nav'].forEach(role=>{const id=raw.choices&&raw.choices[role];if(selected.includes(id)&&BY_ID[id].role===role)choices[role]=id;});const content={};if(raw.content&&typeof raw.content==='object')Object.keys(raw.content).forEach(id=>{if(Object.hasOwn(BY_ID,id)&&Array.isArray(raw.content[id]))content[id]=raw.content[id].slice(0,200).map(v=>typeof v==='string'?v.slice(0,500):null);});const repeat={};if(raw.repeat&&typeof raw.repeat==='object')Object.keys(raw.repeat).forEach(id=>{const n=Number(raw.repeat[id]);if(selected.includes(id)&&BY_ID[id].role==='cards'&&Number.isInteger(n)&&n>1&&n<=MAX_REPEAT)repeat[id]=n;});return {brief:typeof raw.brief==='string'?raw.brief.slice(0,240):'',selected,choices,content,repeat,motion:TintaMotion.normalize(raw.motion),palette:TintaPalettes.normalize(raw.palette),visual:TintaVisual.normalize(raw.visual),background:TintaBackgrounds.normalize(raw.background),mode:raw.mode==='dark'||raw.mode==='light'?raw.mode:null,navStyle:normNavStyle(raw.navStyle),font:TintaFonts.normalize(raw.font),multi:raw.multi===true,flows:Array.isArray(raw.flows)?[...new Set(raw.flows.filter(f=>TintaScreens.FLOWS.includes(f)))]:null,assets:TintaAssets.normalize(raw.assets,BY_ID),ui:TintaStates.normalize(raw.ui,BY_ID),buttonStyles:TintaButtonStyle.normalize(raw.buttonStyles,BY_ID),cardStyles:TintaCardStyle.normalize(raw.cardStyles,BY_ID)};}
