let editingId=null;
function adaptTexts(){const sector=TintaSectors.detect(state.brief);if(!sector){toast('No reconocí el sector. Prueba con: tienda, café, finanzas, gimnasio, viajes, salud, música o curso.');return;}let changed=0,kept=0,offset=0;state.selected.forEach(id=>{const block=BY_ID[id];if(!block||block.role==='nav'||block.fixed||block.copies)return;if(state.content[id]){kept++;return;}const fields=contentModel(block).fields;const out=TintaSectors.fill(sector.id,fields,{offset,role:fillRole(block.id)});offset+=2;if(!out||!out.some(v=>v))return;state.content[id]=(block.role==='header'?brandFix(fields,out.map((v,i)=>v||fields[i].value),sector.id):out.map((v,i)=>v||fields[i].value)).map(v=>String(v).slice(0,500));changed++;});if(!changed){toast(kept?'Tus textos editados a mano se respetan; no hay nada que adaptar.':'No hay bloques con textos que adaptar.');return;}state.composed=false;save('Adaptar textos al sector','adapt-text');renderReview();toast('Textos adaptados a «'+sector.name+'» en '+changed+(changed===1?' bloque':' bloques')+(kept?' · '+kept+' editados a mano se respetan':'')+'. Puedes deshacer.');}
