/* En la app Android la página se carga desde file://, que no sirve como enlace: se usa la dirección pública de la web. */
function shareBase(){return location.protocol==='file:'?'https://criptobox.github.io/Estilos-/index.html':location.origin+location.pathname;}
async function shareLink(){if(!state.selected.length){toast('Elige al menos un bloque antes de compartir.');return;}try{const {code}=await TintaShare.encode(draftSnapshot());const url=shareBase()+'#'+code,box=$('shareBox'),input=$('shareLink');input.value=url;box.hidden=false;$('shareNote').textContent=url.length>TintaShare.LONG_LINK?'Enlace largo ('+url.length+' caracteres): algunas apps lo recortan. Si no abre, usa «Guardar pantalla» y descarga el JSON. ':'';$('shareNote').textContent+='No incluye imágenes subidas.';input.focus();input.select();const copied=await copyToClipboard(url);toast(copied?'Enlace copiado. Quien lo abra lo recibe como copia en Mis proyectos.':'Copia el enlace seleccionado (Ctrl+C).');}catch(e){toast('No se pudo crear el enlace en este navegador.');}}
async function importShared(){const hash=location.hash;if(!TintaShare.isShareHash(hash))return;const clean=()=>history.replaceState(null,'',location.pathname+location.search);try{const raw=await TintaShare.decode(hash),draft=normalizedDraft(raw);clean();openProjects();addProject('Compartido · '+(draft.brief||'Mi pantalla').slice(0,60),draft);}catch(e){clean();renderPage('home',false);toast('El enlace no es válido o usa bloques que no tienes en tu biblioteca.');}}
function openText(id){if(!state.selected.includes(id))return;editingId=id;const model=contentModel(editedBlock(BY_ID[id]));$('textTitle').textContent=BY_ID[id].name;$('textFields').replaceChildren();model.fields.forEach((field,i)=>{const label=document.createElement('label');label.textContent=field.label+' '+(i+1);const input=document.createElement('textarea');input.value=field.value;input.maxLength=500;input.rows=2;input.dataset.field=i;label.appendChild(input);$('textFields').appendChild(label);});if(!model.fields.length)$('textFields').textContent='Este bloque no tiene textos editables.';$('textDialog').showModal();}
$('textForm').addEventListener('submit',ev=>{ev.preventDefault();state.content[editingId]=[...$('textFields').querySelectorAll('textarea')].map(t=>t.value.slice(0,500));state.composed=false;save();renderReview();$('textDialog').close();toast('Textos actualizados. El diseño se conserva.');});
const TINTA_PROJECT_KEY='estilos-tinta-projects-v1';let pendingProject=null;
function projectMessage(message){$('projectMessage').textContent=message;}
function readTintaProjects(){try{const raw=JSON.parse(TintaStore.unpackText(localStorage.getItem(TINTA_PROJECT_KEY))||'[]');if(!Array.isArray(raw)||raw.length>30||raw.some(p=>!p||typeof p.id!=='string'||typeof p.name!=='string'||!p.draft))throw Error();return raw;}catch(e){projectMessage('No se pueden leer los proyectos guardados. No se reemplazará su almacenamiento. Puedes descargar tu pantalla como JSON.');return null;}}
function writeTintaProjects(list){try{localStorage.setItem(TINTA_PROJECT_KEY,TintaStore.packText(JSON.stringify(list)));return true;}catch(e){projectMessage('No se pudo guardar: almacenamiento lleno o bloqueado. Descarga el proyecto como JSON para conservarlo.');return false;}}
function projectId(){return 't-'+(globalThis.crypto&&crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));}
function addProject(name,draft){const list=readTintaProjects();if(!list)return;if(!name.trim()){projectMessage('Pon un nombre a tu pantalla.');$('tintaProjectName').focus();return;}if(!draft.selected.length){projectMessage('Elige al menos un bloque antes de guardar.');return;}if(list.length>=30){projectMessage('Ya tienes 30 proyectos. Descarga o elimina una copia antes de añadir otra.');return;}if(writeTintaProjects([{id:projectId(),name:name.trim().slice(0,80),updated:new Date().toISOString(),draft},...list])){pendingProject=null;renderTintaProjects();projectMessage('Copia guardada: '+name.trim().slice(0,80));}}
function openProjects(){pendingProject=null;projectMessage('');$('tintaProjectName').value=state.brief?state.brief.slice(0,80):'';renderTintaProjects();renderLegacyProjects();$('projectsDialog').showModal();}
function renderLegacyProjects(){const host=$('legacyProjectList');host.replaceChildren();try{const list=JSON.parse(localStorage.getItem('estilos-studio-projects-v1')||'[]');if(!Array.isArray(list))throw Error();list.filter(p=>p&&typeof p.id==='string'&&/^[a-zA-Z0-9-]+$/.test(p.id)&&typeof p.name==='string'&&p.state).slice(0,30).forEach(p=>{const row=document.createElement('div');row.className='legacy-row';const name=document.createElement('span');name.textContent=p.name.slice(0,80);const a=document.createElement('a');a.href='agente.html?projects=1&project='+encodeURIComponent(p.id);a.textContent='Abrir en su editor ↗';row.append(name,a);host.appendChild(row);});if(!host.children.length)host.textContent='No hay proyectos clásicos guardados en este navegador.';}catch(e){host.textContent='Los proyectos clásicos no están accesibles en esta vista. Abre la app en el navegador donde los guardaste.';}}
function renderTintaProjects(){const list=readTintaProjects(),host=$('tintaProjectList');host.replaceChildren();if(!list)return;if(!list.length){const p=document.createElement('p');p.className='dialog-note';p.textContent='Todavía no has guardado proyectos de Tinta.';host.appendChild(p);}list.forEach(p=>{const row=document.createElement('article');row.className='tinta-project';row.dataset.projectId=p.id;const name=document.createElement('input');name.value=p.name.slice(0,80);name.maxLength=80;name.setAttribute('aria-label','Nombre de '+p.name);const meta=document.createElement('small');const date=new Date(p.updated);meta.textContent=(Array.isArray(p.draft.selected)?p.draft.selected.length:0)+' bloques · '+(Number.isNaN(+date)?'Sin fecha':date.toLocaleString('es'));const acts=document.createElement('div');acts.className='project-buttons';[['project-open','Abrir'],['project-rename','Renombrar'],['project-update','Actualizar'],['project-json','JSON'],['project-delete','Eliminar']].forEach(([act,text])=>{const button=document.createElement('button');button.dataset.act=act;button.dataset.projectId=p.id;button.textContent=text;acts.appendChild(button);});row.append(name,meta,acts);if(pendingProject&&pendingProject.id===p.id){const box=document.createElement('div');box.className='project-confirm-tinta';const text=document.createElement('p');text.textContent=pendingProject.act==='project-open'?'Abrir reemplazará tu pantalla de trabajo. Guarda una copia o descarga su JSON si quieres conservarla.':pendingProject.act==='project-update'?'Actualizar sustituirá esta copia por tu pantalla de trabajo actual.':'¿Eliminar esta copia guardada? Tu pantalla de trabajo no se borrará.';box.appendChild(text);[['project-confirm','Sí, continuar'],['project-cancel','Cancelar']].forEach(([act,label])=>{const button=document.createElement('button');button.dataset.act=act;button.dataset.projectId=p.id;button.textContent=label;box.appendChild(button);});row.appendChild(box);}host.appendChild(row);});}
function downloadProject(name,draft){if(!draft.selected.length){projectMessage('Primero elige algún bloque.');return;}const blob=new Blob([JSON.stringify({format:'estilos-tinta-project',version:1,name:name.trim().slice(0,80)||'Mi pantalla',draft},null,2)],{type:'application/json'});if(nativeSave(blob,'proyecto-tinta.json'))return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='proyecto-tinta.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);}
$('saveProjectForm').addEventListener('submit',ev=>{ev.preventDefault();addProject($('tintaProjectName').value,draftSnapshot());});
$('tintaImport').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('El archivo supera el límite de 8 MB.');const data=JSON.parse(await file.text());if(data.format!=='estilos-tinta-project'||data.version!==1||typeof data.name!=='string')throw Error('Formato no válido. Importa un proyecto JSON de Tinta (versión 1).');const draft=normalizedDraft(data.draft);addProject(data.name,draft);}catch(e){projectMessage(e.message||'No se pudo importar.');}finally{ev.target.value='';}});
function projectAction(act,id){const list=readTintaProjects();if(!list)return;const project=list.find(p=>p.id===id);if(!project){projectMessage('El proyecto ya no está disponible.');return;}if(act==='project-json'){downloadProject(project.name,project.draft);return;}if(act==='project-rename'){const row=[...$('tintaProjectList').children].find(el=>el.dataset.projectId===id);const name=row.querySelector('input').value.trim().slice(0,80);if(!name){projectMessage('El nombre no puede estar vacío.');return;}if(writeTintaProjects(list.map(p=>p.id===id?{...p,name}:p))){renderTintaProjects();projectMessage('Nombre actualizado.');}return;}if(act==='project-cancel'){pendingProject=null;renderTintaProjects();return;}if(['project-open','project-update','project-delete'].includes(act)){pendingProject={id,act};renderTintaProjects();return;}if(act!=='project-confirm'||!pendingProject||pendingProject.id!==id)return;const action=pendingProject.act;if(action==='project-open'){try{const draft=normalizedDraft(project.draft);Object.assign(state,draft);state.composed=false;$('idea').value=state.brief;resetDraftHistory();save();pendingProject=null;$('projectsDialog').close();go('review');toast('Proyecto abierto: '+project.name);}catch(e){projectMessage(e.message);}return;}if(action==='project-update'&&!state.selected.length){projectMessage('La pantalla está vacía. No se actualizó la copia.');return;}const next=action==='project-delete'?list.filter(p=>p.id!==id):list.map(p=>p.id===id?{...p,draft:draftSnapshot(),updated:new Date().toISOString()}:p);if(writeTintaProjects(next)){pendingProject=null;renderTintaProjects();projectMessage(action==='project-delete'?'Copia eliminada.':'Copia actualizada.');}}
{const cf=$('chatForm');if(cf){cf.addEventListener('submit',ev=>{ev.preventDefault();chatSend($('chatInput').value);});$('chatInput').addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing&&innerWidth>720){ev.preventDefault();chatSend($('chatInput').value);}});$('chatModel').addEventListener('change',ev=>{const [p,...m]=String(ev.target.value).split('|');if(p)ia.setActive(p,m.join('|'));});}}
{const f=$('paletteImgFile');if(f)f.addEventListener('change',()=>{palImgOpen(f.files&&f.files[0]);f.value='';});const dd=$('paletteImgDialog');if(dd)dd.addEventListener('click',ev=>{const m=ev.target.closest('[data-pal-mode]');if(m){palImg.mode=m.dataset.palMode;palImgPaint();}});if(dd)dd.addEventListener('close',()=>{if(palImg.url){URL.revokeObjectURL(palImg.url);palImg.url=null;}});}
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-act]');if(!button)return;const act=button.dataset.act;if(act==='open-chat'){openChat();return;}if(act==='close-chat'){$('chatDialog').close();return;}if(act==='chat-idea'){chatSend(button.textContent);return;}if(act==='chat-retry'){button.closest('.msg').remove();chatAsk();return;}if(act==='chat-team'){const m=chat.all()[+button.dataset.i];if(m)chatToTeam(m.content);return;}if(act==='rec-open'){recOpenChat(button.dataset.chat);return;}if(act==='rec-paste'){recPaste();return;}if(act==='open-github'){openGH();return;}if(act==='close-gh'){$('ghDialog').close();return;}if(act==='gh-verify'){ghVerify();return;}if(act==='gh-forget'){gh.clear();$('ghToken').value='';$('ghRepos').textContent='';ghStatus('Token olvidado: ya no queda en este dispositivo.');return;}if(act==='gh-push'){ghPush();return;}if(act==='open-team'){openTeam();return;}if(act==='open-ia'){openIA();return;}if(act==='close-ia'){$('iaDialog').close();recAiNote();if($('chatDialog').open)chatRenderModels();return;}if(act==='ia-connect'){iaConnect();return;}if(act==='ia-use'){if(ia.setActive(iaProv().id,button.dataset.model)){iaRender();recAiNote();if($('chatDialog').open)chatRenderModels();}return;}if(act==='ia-forget'){ia.forget(iaProv().id);iaLive=null;$('iaKey').value='';iaSay('Clave y modelos de este proveedor olvidados.');iaRender();recAiNote();return;}if(act==='ia-provider'){iaSel=button.dataset.id;iaLive=null;iaSay('');$('iaKey').value='';iaRender();return;}if(act==='ia-eye'){const k=$('iaKey');k.type=k.type==='password'?'text':'password';return;}if(act==='rec-ai'){recAI();return;}if(act==='open-receta'){openReceta();return;}if(act==='close-receta'){$('recetaDialog').close();return;}if(act==='rec-copy'){recCopy(receta().prompt($('recIdea').value),'Prompt copiado. Pégalo en tu chat y copia su respuesta.');return;}if(act==='rec-build'){recBuild();return;}if(act==='rec-fix'){recCopy(receta().fixPrompt(recLast),'Mensaje copiado. Pégalo en el mismo chat y copia la nueva respuesta.');return;}if(act==='palette-from-image'){$('paletteImgFile').click();return;}if(act==='close-palette-img'){palImgClose();return;}if(act==='save-palette-img'){palImgSave();return;}if(act==='delete-palette'){deletePalette(button.dataset.id);return;}if(act==='edit-text')openText(button.dataset.id);if(act==='adapt-text')adaptTexts();if(act==='use-template')useTemplate(button.dataset.id);if(act==='use-motion')useMotion(button.dataset.id);if(act==='use-visual')useVisual(button.dataset.id);if(act==='use-background')useBackground(button.dataset.id);if(act==='use-font')useFont(button.dataset.id);if(act==='use-palette')usePalette(button.dataset.id);if(act==='view-screen')setScreenView(button.dataset.id);if(act==='backup-open')openBackup();if(act==='close-backup')$('backupDialog').close();if(act==='backup-download')downloadBackup();if(act==='backup-apply')applyBackup();if(act==='new-mystyle')openStyleDialog(null,true);if(act==='close-mystyle')$('styleDialog').close();if(act==='clone-mystyle'){const b=mineBlock();if(b)openStyleDialog(b.raw,true);}if(act==='edit-mystyle'){const b=mineBlock();if(b&&b.mine)openStyleDialog(b.raw,false);}if(act==='delete-mystyle')deleteMyStyle();if(act==='share-link')shareLink();if(act==='close-text')$('textDialog').close();if(act==='reset-text'){delete state.content[editingId];state.composed=false;save();renderReview();$('textDialog').close();toast('Textos originales restaurados.');}if(act==='projects'||act==='save-dialog')openProjects();if(act==='close-projects')$('projectsDialog').close();if(act==='backup-draft')downloadProject($('tintaProjectName').value,draftSnapshot());if(act.startsWith('project-'))projectAction(act,button.dataset.projectId);});

document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const action=b.dataset.act,id=b.dataset.id;if(action==='go'){if(b.dataset.page==='explore'&&state.page==='explore'&&(b.closest('.site-header')||b.closest('.site-menu')))libLast='#bloques';go(b.dataset.page);}if(action==='filter'){state.filter=b.dataset.filter;renderGallery();}if(action==='chosen'){state.chosenOnly=!state.chosenOnly;renderGallery();}if(action==='fav')toggleFav(id);if(action==='favs-only'){state.favsOnly=!state.favsOnly;renderGallery();}if(action==='recent-only'){state.recentOnly=!state.recentOnly;renderGallery();}if(action==='select')toggle(id);if(action==='detail')openDetail(id);if(action==='close-detail')$('detailDialog').close();if(action==='select-detail')toggle(detailId);if(action==='clear'){state.selected=[];state.choices={header:null,nav:null};state.composed=false;save();renderGallery();toast('Selección vacía. Tu idea sigue guardada.');}if(action==='compose'){if(conflicts().length||!state.selected.length)return;state.composed=true;renderReview();save();toast('Tu pantalla está compuesta. No cambié tus bloques.');if(innerWidth<721)document.querySelector('.composition-area').scrollIntoView({behavior:'smooth',block:'start'});}if(action==='export')download();if(action==='idea'){const ideas={tienda:'Una tienda de ropa con tarjetas de producto y una barra inferior.',comida:'Una app para mi cafetería, con tarjetas grandes y una navegación sencilla.',finanzas:'Una app de finanzas personales con un balance claro y tarjetas con relieve.',libre:''};state.brief=ideas[b.dataset.idea]||'';$('idea').value=state.brief;save();$('idea').focus();}if(action==='hello'){const avatar=document.querySelector('.avatar-button');avatar.classList.remove('hello');void avatar.offsetWidth;avatar.classList.add('hello');$('greeting').innerHTML='Vamos a crear algo <b>muy tuyo.</b>';setTimeout(()=>avatar.classList.remove('hello'),800);}if(action==='menu'){const open=$('siteMenu').hidden;$('siteMenu').hidden=!open;b.setAttribute('aria-expanded',open);}if(action==='reset'){state.content={};state.assets={};state.repeat={};state.motion={};state.palette=null;state.visual=null;state.background=null;state.mode=null;state.navStyle=null;state.font=null;state.multi=false;state.flows=null;state.ui={};state.buttonStyles={};state.cardStyles={};state.selected=[];state.choices={header:null,nav:null};state.brief='';state.composed=false;$('idea').value='';save();go('home');toast('Un lienzo nuevo. Tus proyectos del editor clásico no se modificaron.');}if(action==='move'){const ids=idsFor(BY_ID[id].role),from=ids.indexOf(id),to=from+Number(b.dataset.dir);if(from<0||to<0||to>=ids.length)return;const a=state.selected.indexOf(id),z=state.selected.indexOf(ids[to]);[state.selected[a],state.selected[z]]=[state.selected[z],state.selected[a]];state.composed=false;save();renderReview();}});
document.addEventListener('change',ev=>{const input=ev.target.closest('[data-choice]');if(!input)return;const id=input.value,role=input.dataset.choice;if(state.selected.includes(id)&&BY_ID[id].role===role){state.choices[role]=id;state.composed=false;save();renderReview();}});
$('idea').addEventListener('input',ev=>{state.brief=ev.target.value.slice(0,240);save('Editar idea','brief');});$('briefForm').addEventListener('submit',ev=>{ev.preventDefault();if(!state.brief.trim()){toast('Cuéntame una idea o entra a elegir tus bloques.');$('idea').focus();return;}suggest();});
document.addEventListener('click',ev=>{if(!ev.target.closest('.site-menu,.menu-button')){$('siteMenu').hidden=true;document.querySelector('.menu-button').setAttribute('aria-expanded','false');}});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){$('siteMenu').hidden=true;document.querySelector('.menu-button').setAttribute('aria-expanded','false');}});$('detailDialog').addEventListener('click',ev=>{if(ev.target===$('detailDialog')){const r=$('detailDialog').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('detailDialog').close();}});
window.addEventListener('hashchange',()=>applyRoute());window.addEventListener('resize',fitPhone);
document.querySelectorAll('[data-act=filter]').forEach(button=>{if(button.dataset.filter==='all')return;const badge=document.createElement('span');badge.textContent=CATALOG.filter(b=>b.role===button.dataset.filter).length;button.appendChild(badge);});
Object.entries(ROLES).forEach(([role,label])=>{const option=document.createElement('option');option.value=role;option.textContent=label+' · '+CATALOG.filter(b=>b.role===role).length;$('catalogCategory').appendChild(option);});$('catalogSearch').addEventListener('input',ev=>{state.query=ev.target.value.slice(0,120);renderGallery();});$('catalogCategory').addEventListener('change',ev=>{state.filter=ev.target.value;renderGallery();});$('catalogSource').addEventListener('change',ev=>{state.source=ev.target.value;renderGallery();});
TintaCatalog.modules.forEach(module=>{const n=RECORDS.filter(r=>r.module===module.id).length,option=document.createElement('option');option.value=module.id;option.textContent=module.number+' · '+module.name+' · '+(n||'sin recursos');option.disabled=!n;$('catalogModule').appendChild(option);});$('catalogModule').addEventListener('change',ev=>{state.module=ev.target.value;renderGallery();});$('catalogStyle').addEventListener('change',ev=>{state.style=ev.target.value;renderGallery();});
// Inspector temporal: nunca selecciona recursos ni modifica el borrador hasta Aplicar.
let stylingId=null,styleConfig=null;
const styleFields={target:'Target',format:'Format',background:'Background',foreground:'Foreground',secondary:'Secondary',radius:'Radius',padding:'Padding',fontSize:'FontSize',shadow:'Shadow'};
function fillStyleFields(){Object.entries(styleFields).forEach(([key,suffix])=>$('style'+suffix).value=styleConfig[key]);}
function refreshButtonStyle(){if(!stylingId)return;$('buttonStylePreview').replaceChildren(makeBlock(BY_ID[stylingId],undefined,styleConfig));const c=styleConfig;let ratio=TintaButtonStyle.contrast(c.background,c.foreground);if(c.format==='gradient')ratio=Math.min(ratio,TintaButtonStyle.contrast(c.secondary,c.foreground));$('buttonStyleContrast').textContent=c.format==='original'?'Se conserva el acabado original; al cambiar una propiedad se activará Color sólido.':c.format==='outline'||c.format==='soft'?'Fondo transparente o tonal: verifica la legibilidad sobre la superficie del diseño. El color de texto es independiente del borde.':'Contraste orientativo de los colores: '+ratio.toFixed(2)+':1. '+(ratio<4.5?'Atención: por debajo de 4.5:1 para texto normal.':'Los colores alcanzan 4.5:1 para texto normal.')+(c.format==='gradient'?' En un degradado revisa también las zonas intermedias.':'');$('styleSecondary').disabled=c.format!=='gradient';}
function openButtonStyle(id){if(!Object.hasOwn(BY_ID,id)||!TintaButtonStyle.supports(BY_ID[id]))return;const block=BY_ID[id];stylingId=id;styleConfig={...(state.buttonStyles[id]||TintaButtonStyle.defaults(block))};const targets=TintaButtonStyle.targets(editedBlock(block));$('styleTarget').replaceChildren();targets.forEach((target,i)=>{const option=document.createElement('option');option.value=i;option.textContent=(i+1)+'. '+(target.getAttribute('aria-label')||target.textContent.trim()||'Botón sin texto').slice(0,70)+(target.disabled?' · deshabilitado':'');$('styleTarget').appendChild(option);});if(styleConfig.target>=targets.length)styleConfig.target=0;$('buttonStyleTitle').textContent=block.name;fillStyleFields();$('buttonStyleMessage').textContent='Solo se aplica al botón elegido dentro de este bloque. Los demás conservan su aspecto. El estilo personal tiene prioridad sobre el acabado del laboratorio de estados.';refreshButtonStyle();if(!$('buttonStyleDialog').open)$('buttonStyleDialog').showModal();}
function refreshAfterStyle(){state.composed=false;const stored=save();renderReview();renderGallery();if(detailId===stylingId&&$('detailDialog').open)openDetail(detailId);return stored;}
$('buttonStyleForm').addEventListener('input',ev=>{const entry=Object.entries(styleFields).find(([,suffix])=>ev.target.id==='style'+suffix);if(!entry||!styleConfig)return;const key=entry[0];if(['target','radius','padding','fontSize'].includes(key)){if(!ev.target.checkValidity())return;styleConfig[key]=Number(ev.target.value);}else styleConfig[key]=ev.target.value;if(!['target','format'].includes(key)&&styleConfig.format==='original'){styleConfig.format='solid';$('styleFormat').value='solid';}refreshButtonStyle();});
function applyButtonStyle(ev){if(ev)ev.preventDefault();if(!stylingId||!$('buttonStyleForm').reportValidity())return;try{const valid=TintaButtonStyle.normalize({[stylingId]:styleConfig},BY_ID);state.buttonStyles[stylingId]=valid[stylingId];const stored=refreshAfterStyle();$('buttonStyleDialog').close();toast(stored?'Color y estilo aplicados.':'Estilo aplicado en esta sesión. No se pudo guardar: descarga el JSON.');}catch(e){$('buttonStyleMessage').textContent=e.message;}}
$('buttonStyleForm').addEventListener('submit',applyButtonStyle);
$('buttonStyleForm').addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.matches('input'))applyButtonStyle(ev);});
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-act]');if(!button)return;switch(button.dataset.act){case 'apply-button-style':applyButtonStyle();break;case 'button-style':openButtonStyle(button.dataset.id);break;case 'style-current':openButtonStyle(detailId);break;case 'close-button-style':$('buttonStyleDialog').close();break;case 'style-preset':if(!styleConfig)return;styleConfig.format='solid';styleConfig.background=button.dataset.color;styleConfig.foreground='#ffffff';fillStyleFields();refreshButtonStyle();break;case 'reset-button-style':if(!stylingId)return;delete state.buttonStyles[stylingId];const stored=refreshAfterStyle();$('buttonStyleDialog').close();toast(stored?'Estilo original restaurado.':'Original restaurado en esta sesión; descarga el JSON para conservarlo.');break;case 'toggle-theme':setUITheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);break;}});
