function cardStyleMessage(message){$('cardStyleMessage').textContent=message;}
function refreshCardStyle(){if(!cardStylingId)return;const c=cardStyleConfig;$('cardStylePreview').replaceChildren(makeBlock(BY_ID[cardStylingId],undefined,undefined,c));$('cardStyleSecondary').disabled=c.format!=='gradient';$('cardStyleAngle').disabled=c.format!=='gradient';$('cardStyleForeground').disabled=c.textMode!=='custom';let ratio=TintaButtonStyle.contrast(c.background,c.foreground);if(c.format==='gradient')ratio=Math.min(ratio,TintaButtonStyle.contrast(c.secondary,c.foreground));$('cardStyleContrast').textContent=c.format==='original'?'Aspecto original intacto. Al cambiar una propiedad se activará Color sólido.':c.textMode==='original'?'Se conservan los colores de texto originales. Comprueba su legibilidad sobre el nuevo fondo.':'Contraste orientativo: '+ratio.toFixed(2)+':1. '+(ratio<4.5?'Atención: por debajo de 4.5:1 para texto normal.':'Los colores alcanzan 4.5:1 para texto normal.')+' No certifica el contraste sobre fotos, capas internas ni zonas intermedias del degradado.';}
/* Estilos de tarjeta listos: una fila de píldoras con su muestra de color. */
function renderCardPresets(){const row=$('cardPresets');if(!row||row.dataset.ready)return;row.dataset.ready='1';TintaPresets.CARD_PRESETS.forEach(P=>{const b=document.createElement('button');b.type='button';b.dataset.act='card-preset';b.dataset.id=P.id;b.setAttribute('aria-pressed','false');b.title=P.desc;const i=document.createElement('i');i.style.background=P.v.format==='gradient'?'linear-gradient('+P.v.angle+'deg,'+P.v.background+','+P.v.secondary+')':P.v.background;i.setAttribute('aria-hidden','true');b.append(i,document.createTextNode(P.name));row.appendChild(b);});}
function paintCardPresets(id){document.querySelectorAll('#cardPresets button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));}
function fillCardStyle(){Object.entries(cardStyleFields).forEach(([key,suffix])=>$('cardStyle'+suffix).value=cardStyleConfig[key]);refreshCardStyle();}
function readCardStyleDefaults(block){const cfg=TintaCardStyle.defaults(block),host=makeBlock(block);$('cardStylePreview').replaceChildren(host);const root=host.shadowRoot.querySelector('[data-ts=card]')||host.shadowRoot,el=TintaCardStyle.nodes(root,block)[0];if(!el)return cfg;const css=getComputedStyle(el),hex=(value,fallback)=>{if(!/^rgba?\(/.test(value))return fallback;const parts=value.match(/[\d.]+/g);if(!parts||parts.length<3||(parts.length>3&&Number(parts[3])<1))return fallback;return '#'+parts.slice(0,3).map(n=>Math.round(Number(n)).toString(16).padStart(2,'0')).join('');};cfg.background=hex(css.backgroundColor,cfg.background);cfg.foreground=hex(css.color,cfg.foreground);cfg.borderColor=hex(css.borderTopColor,cfg.borderColor);for(const [key,value,max] of [['radius',css.borderTopLeftRadius,48],['padding',css.paddingTop,32],['borderWidth',css.borderTopWidth,8]])cfg[key]=Math.min(max,Math.max(0,Math.round(parseFloat(value)||0)));cfg.shadow=css.boxShadow==='none'?'none':'soft';return cfg;}
function openCardStyle(id){if(!Object.hasOwn(BY_ID,id)||!TintaCardStyle.supports(BY_ID[id]))return;cardStylingId=id;const block=BY_ID[id];cardStyleConfig={...(state.cardStyles[id]||readCardStyleDefaults(block))};const picker=$('cardStyleTarget');picker.replaceChildren();TintaCardStyle.targets(editedBlock(block)).forEach((el,index)=>{const option=document.createElement('option');option.value=index;option.textContent=(index+1)+'. '+(el.querySelector('h1,h2,h3,b,strong')?.textContent.trim()||el.textContent.trim()||'Superficie de tarjeta').replace(/\s+/g,' ').slice(0,65);picker.appendChild(option);});$('cardStyleTitle').textContent=block.name;cardStyleMessage('Vista temporal: no cambia tu selección. Solo se personaliza la superficie elegida; las demás conservan el original.');renderCardPresets();paintCardPresets(null);fillCardStyle();$('cardStyleDialog').showModal();}
function commitCardStyle(reset=false){if(!cardStylingId||(!reset&&!$('cardStyleForm').reportValidity()))return;try{if(reset)delete state.cardStyles[cardStylingId];else state.cardStyles[cardStylingId]=TintaCardStyle.normalize({[cardStylingId]:cardStyleConfig},BY_ID)[cardStylingId];state.composed=false;const stored=save();renderReview();renderGallery();if(detailId===cardStylingId&&$('detailDialog').open)openDetail(detailId);$('cardStyleDialog').close();toast((reset?'Estilo original restaurado.':'Estilo de tarjeta aplicado.')+(stored?'':' Solo en esta sesión: no se pudo guardar; descarga el JSON.'));}catch(e){cardStyleMessage(e.message);}}
$('cardStyleForm').addEventListener('input',ev=>{if(!cardStyleConfig)return;const field=Object.entries(cardStyleFields).find(([,suffix])=>ev.target.id==='cardStyle'+suffix);if(!field)return;const key=field[0];if(['target','radius','padding','borderWidth','angle'].includes(key)){if(!ev.target.checkValidity())return;cardStyleConfig[key]=Number(ev.target.value);}else cardStyleConfig[key]=ev.target.value;if(!['target','format'].includes(key)&&cardStyleConfig.format==='original'){cardStyleConfig.format='solid';$('cardStyleFormat').value='solid';}refreshCardStyle();});
