document.addEventListener('click',ev=>{const button=ev.target.closest('[data-act]');if(!button||button.disabled)return;switch(button.dataset.act){case 'card-style':openCardStyle(button.dataset.id);break;case 'card-style-current':openCardStyle(detailId);break;case 'close-card-style':$('cardStyleDialog').close();break;case 'apply-card-style':commitCardStyle();break;case 'reset-card-style':commitCardStyle(true);break;case 'card-preset':{const P=TintaPresets.getCard(button.dataset.id);if(!P||!cardStyleConfig)return;cardStyleConfig={...cardStyleConfig,...P.v,target:cardStyleConfig.target};fillCardStyle();paintCardPresets(P.id);cardStyleMessage('Estilo «'+P.name+'» listo. Puedes afinarlo y pulsa «Aplicar».');break;}case 'style-format':{if(!styleConfig)return;const f=button.dataset.format;styleConfig.format=f;styleConfig.foreground=(f==='outline'||f==='soft')?styleConfig.background:'#ffffff';fillStyleFields();refreshButtonStyle();break;}}});

// Solo cambios aplicados del borrador. El historial no sale de esta sesión.
function renderHistory(){const h=draftHistory.status();$('undoDraft').disabled=!h.canUndo;$('redoDraft').disabled=!h.canRedo;for(const [id,label,next,key] of [['undoDraft','Deshacer',h.undoLabel,'Z'],['redoDraft','Rehacer',h.redoLabel,'Mayús+Z']]){const title=label+(next?': '+next:'')+' · Ctrl/⌘+'+key;$(id).title=title;$(id).setAttribute('aria-label',label+(next?': '+next:''));}const statusText='Esta sesión · '+h.undoCount+' para deshacer · '+h.redoCount+' para rehacer'+(h.trimmed?' · se liberaron los cambios más antiguos':'');if($('historyStatus').textContent!==statusText)$('historyStatus').textContent=statusText;}
function resetDraftHistory(){draftHistory.reset(draftSnapshot());historyReady=true;renderHistory();}
function moveDraftHistory(direction){if(document.querySelector('dialog[open]'))return;const result=direction<0?draftHistory.undo():draftHistory.redo();if(!result)return;try{const draft=normalizedDraft(result.draft);Object.assign(state,draft);state.composed=false;$('idea').value=state.brief;historyApplying=true;const stored=save();historyApplying=false;renderGallery();renderReview();paintMotion();paintPalettes();paintVisuals();if(state.page==='review'&&!state.selected.length)go('explore');renderHistory();toast((direction<0?'Deshecho: ':'Rehecho: ')+result.label+(stored?'':'. Solo en esta sesión: no se pudo guardar; descarga el JSON.'));}catch(e){historyApplying=false;if(direction<0)draftHistory.redo();else draftHistory.undo();renderHistory();toast('No se pudo recuperar este cambio: '+e.message);}}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;if(b.dataset.act==='undo-draft')moveDraftHistory(-1);if(b.dataset.act==='redo-draft')moveDraftHistory(1);});
